B.bft=new A.bo("\u0627\u0644\u0642\u0631\u0627\u0621\u0629 \u0628\u0650\u0627\u0644\u0633\u064a\u0646 \u0641\u064a ( \u0648\u064e\u064a\u064e\u0628\u06e1\u0635\u06dc\u064f\u0637\u064f )","\u062a\u064f\u0642\u0631\u0623 \u0643\u0644\u0645\u0629 ( \u0648\u064e\u064a\u064e\u0628\u06e1\u0635\u06dc\u064f\u0637\u064f ) \u0628\u0650\u0648\u062c\u0647 \u0648\u0627\u062d\u062f \u0641\u0642\u0637 \u0648\u0647\u0648 \u0628\u0650\u0627\u0644\u0633\u064a\u0646 \u0644\u062d\u0641\u0635 \u0645\u0646 \u0637\u0631\u064a\u0642 \u0627\u0644\u0634\u0627\u0637\u0628\u064a\u0629\u060c \u0641\u062a\u064f\u0642\u0631\u0623 ( \u0648\u064e\u064a\u064e\u0628\u06e1\u0633\u064f\u0637\u064f ). \u0648\u0642\u064f\u0631\u0650\u0623 \u0628\u0650\u0627\u0644\u0633\u064a\u0646 \u0648\u0628\u0650\u0627\u0644\u0635\u0627\u062f \u0645\u0646 \u0637\u0631\u064a\u0642 \u0637\u064a\u0628\u0629 \u0627\u0644\u0646\u0634\u0631.\n\n\u062a\u0646\u0628\u064a\u0647: \u064a\u0646\u0628\u063a\u064a \u0627\u0644\u0627\u0646\u062a\u0628\u0627\u0647 \u0644\u062a\u0631\u0642\u064a\u0642 \u0627\u0644\u0633\u064a\u0646 \u0644\u0645\u062c\u0627\u0648\u0631\u062a\u0647\u0627 \u0627\u0644\u0637\u0627\u0621 \u0644\u0643\u064a\u0644\u0627 \u062a\u0635\u0628\u062d \u0635\u0627\u062f\u064b\u0627 \u0625\u0630\u0627 \u0641\u064f\u062e\u0651\u0650\u0645\u062a\u060c \u0648\u0643\u0630\u0644\u0643 \u064a\u0646\u0628\u063a\u064a \u0627\u0644\u0627\u0646\u062a\u0628\u0627\u0647 \u0644\u062a\u0631\u0642\u064a\u0642 \u0627\u0644\u064a\u0627\u0621 \u0648\u0627\u0644\u0628\u0627\u0621 \u0641\u064a \u0643\u0644\u0645\u0629 ( \u064a\u064e\u0642\u06e1\u0628\u0650\u0636\u064f ) \u0644\u0645\u062c\u0627\u0648\u0631\u062a\u0647\u0645\u0627 \u0627\u0644\u0642\u0627\u0641 \u0648\u0627\u0644\u0636\u0627\u062f.\n\n\u0645\u0644\u0627\u062d\u0638\u0629: \u0641\u064a \u0643\u0644\u0645\u0629 ( \u0648\u064e\u064a\u064e\u0628\u06e1\u0635\u06dc\u064f\u0637\u064f ) \u064a\u064f\u0631\u0633\u0645 \u0641\u0648\u0642 \u062d\u0631\u0641 \u0627\u0644\u0635\u0627\u062f \u0633\u0650\u064a\u0646 \u0635\u063a\u064a\u0631\u0629 \u0625\u0634\u0627\u0631\u0629 \u0625\u0644\u0649 \u0648\u062c\u0648\u062f \u0648\u062c\u0647\u064a\u0646 \u0641\u064a \u0642\u0631\u0627\u0621\u0629 \u0627\u0644\u0635\u0627\u062f\u060c \u0648\u0628\u0645\u0627 \u0623\u0646 \u0627\u0644\u0633\u064a\u0646 \u0631\u064f\u0633\u0645\u062a \u0641\u0648\u0642 \u0627\u0644\u0635\u0627\u062f \u0641\u0627\u0644\u0646\u0637\u0642 \u0628\u0650\u0627\u0644\u0633\u064a\u0646 \u0623\u0634\u0647\u0631\u060c \u0644\u0643\u0646 \u0645\u0646 \u0637\u0631\u064a\u0642 \u0627\u0644\u0634\u0627\u0637\u0628\u064a\u0629 \u064a\u062c\u0648\u0632 \u0648\u062c\u0647 \u0648\u0627\u062d\u062f \u0648\u0647\u0648 \u0627\u0644\u0642\u0631\u0627\u0621\u0629 \u0628\u0650\u0627\u0644\u0633\u064a\u0646 \u0627\u0644\u062e\u0627\u0644\u0635\u0629\u060c \u0643\u0630\u0644\u0643 \u0641\u064a \u0642\u0648\u0644\u0647 \u062a\u0639\u0627\u0644\u0649: ( \u0648\u064e\u0632\u064e\u0627\u062f\u064e\u0643\u064f\u0645\u06e1 \u0641\u0650\u064a \u0671\u0644\u06e1\u062e\u064e\u0644\u06e1\u0642\u0650 \u0628\u064e\u0635\u06dc\u06e1\u0637\u064e\u0629\u064b ) \u064a\u062c\u0648\u0632 \u0648\u062c\u0647 \u0648\u0627\u062d\u062f \u0648\u0647\u0648 \u0627\u0644\u0642\u0631\u0627\u0621\u0629 \u0628\u0650\u0627\u0644\u0633\u064a\u0646 \u0627\u0644\u062e\u0627\u0644\u0635\u0629\u060c \u0648\u0642\u0631\u0623 \u062d\u0641\u0635 \u0645\u0646 \u0637\u0631\u064a\u0642 \u0637\u064a\u0628\u0629 \u0627\u0644\u0646\u0634\u0631 \u0628\u0627\u0644\u0648\u062c\u0647\u064a\u0646 \u0641\u064a \u0627\u0644\u0622\u064a\u062a\u064a\u0646.",B.ahv)
