B.b_8=new A.w("\u062a\u0638\u0647\u0631 \u0627\u0644\u0642\u0644\u0642\u0644\u0629 \u0641\u064a \u062d\u0631\u0648\u0641 \u0627\u0644\u0642\u0644\u0642\u0644\u0629 \u0639\u0646\u062f\u0645\u0627 \u064a\u0643\u0648\u0646 \u0627\u0644\u062d\u0631\u0641 \u0633\u0627\u0643\u0646\u064b\u0627\u060c \u0641\u0647\u0644 \u062a\u0638\u0647\u0631 \u0627\u0644\u0642\u0644\u0642\u0644\u0629 \u0641\u064a \u062d\u0631\u0641 \u0627\u0644\u0642\u0627\u0641 \u0641\u064a \u0643\u0644\u0645\u0629 ( \u0671\u0644\u06e1\u0641\u064e\u0644\u064e\u0642\u0650 )",B.a9t,"\u0646\u0639\u0645\u060c \u0639\u0646\u062f \u0627\u0644\u0648\u0642\u0641 \u0641\u0642\u0637","\u0639\u0646\u062f \u0627\u0644\u0648\u0642\u0641 \u0639\u0644\u0649 \u062d\u0631\u0641 \u0645\u062a\u062d\u0631\u0643 ( \u0645\u0641\u062a\u0648\u062d \u0623\u0648 \u0645\u0643\u0633\u0648\u0631 \u0623\u0648 \u0645\u0636\u0645\u0648\u0645 ) \u0641\u0625\u0646 \u062d\u0631\u0643\u062a\u0647 \u062a\u064f\u0628\u064e\u062f\u0651\u0644 \u0625\u0644\u0649 \u0633\u0643\u0648\u0646 \u0644\u0623\u0646 \u0627\u0644\u0639\u0631\u0628 \u0644\u0627 \u062a\u0642\u0641 \u0639\u0644\u0649 \u0645\u062a\u062d\u0631\u0643\u060c \u0648\u0627\u0644\u0642\u0644\u0642\u0644\u0629 \u062a\u0638\u0647\u0631 \u0639\u0646\u062f\u0645\u0627 \u064a\u0643\u0648\u0646 \u0627\u0644\u062d\u0631\u0641 \u0633\u0627\u0643\u0646\u064b\u0627\u060c \u0641\u0639\u0646\u062f \u0627\u0644\u0648\u0642\u0641 \u0639\u0644\u0649 \u0643\u0644\u0645\u0629 \u062a\u0646\u062a\u0647\u064a \u0628\u062d\u0631\u0641 \u0645\u0646 \u062d\u0631\u0648\u0641 \u0627\u0644\u0642\u0644\u0642\u0644\u0629 \u062a\u0638\u0647\u0631 \u0641\u064a\u0647 \u0627\u0644\u0642\u0644\u0642\u0644\u0629. \u0641\u0643\u0644\u0645\u0629 ( \u0671\u0644\u06e1\u0641\u064e\u0644\u064e\u0642\u0650 ) \u062a\u0646\u062a\u0647\u064a \u0628\u062d\u0631\u0641 \u0627\u0644\u0642\u0627\u0641 \u0648\u0647\u0648 \u0645\u0646 \u062d\u0631\u0648\u0641 \u0627\u0644\u0642\u0644\u0642\u0644\u0629 \u0648\u0647\u064a ( \u0642\u064f\u0637\u0652\u0628\u064f \u062c\u064e\u062f\u0652 )\u060c \u0648\u062a\u0643\u0648\u0646 \u0627\u0644\u0642\u0644\u0642\u0644\u0629 \u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u0645\u062b\u0627\u0644 \u0639\u0646\u062f \u0627\u0644\u0648\u0642\u0641 \u0641\u0642\u0637\u060c \u0644\u0623\u0646 \u0627\u0644\u0642\u0627\u0641 \u0645\u0643\u0633\u0648\u0631\u0629 \u0639\u0646\u062f \u0627\u0644\u0648\u0635\u0644 \u0641\u0644\u0627 \u064a\u0648\u062c\u062f \u0641\u064a\u0647\u0627 \u0642\u0644\u0642\u0644\u0629 \u0648\u0644\u0643\u0646 \u0639\u0646\u062f \u0627\u0644\u0648\u0642\u0641 \u0639\u0644\u064a\u0647\u0627 \u062a\u064f\u0628\u064e\u062f\u0651\u0644 \u0627\u0644\u062d\u0631\u0643\u0629 ( \u0627\u0644\u0643\u0633\u0631\u0629 ) \u0628\u0627\u0644\u0633\u0643\u0648\u0646 \u0641\u062a\u062c\u0628 \u0627\u0644\u0642\u0644\u0642\u0644\u0629.")
B.a8t=A.a(s(["\u0625\u0650\u0630\u064e\u0627 \u0648\u064e\u0642\u064e\u0628\u064e","\u0645\u064e\u0644\u0650\u0643\u0650 \u0671\u0644\u0646\u0651\u064e\u0627\u0633\u0650","\u0625\u0650\u0646\u0651\u064e\u0627\u0653 \u0623\u064e\u0639\u06e1\u0637\u064e\u064a\u06e1\u0646\u064e\u0670\u0643\u064e \u0671\u0644\u06e1\u0643\u064e\u0648\u06e1\u062b\u064e\u0631\u064e","\u064a\u064e\u062f\u064f\u0639\u0651\u064f \u0671\u0644\u06e1\u064a\u064e\u062a\u0650\u064a\u0645\u064e"]),t.s)
