B.aZr=new A.w(u.p,B.a6S,"\u0648\u064e\u062a\u064e\u0648\u064e\u0627\u0635\u064e\u0648\u06e1\u0627\u0652 \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650","\u0642\u0648\u0644\u0647 \u062a\u0639\u0627\u0644\u0649: ( \u0648\u064e\u062a\u064e\u0648\u064e\u0627\u0635\u064e\u0648\u06e1\u0627\u0652 \u0628\u0650\u0671\u0644\u06e1\u062d\u064e\u0642\u0651\u0650 ) \u064a\u0646\u062a\u0647\u064a \u0628\u062d\u0631\u0641 \u0627\u0644\u0642\u0627\u0641 \u0648\u0647\u0648 \u0645\u0646 \u062d\u0631\u0648\u0641 \u0627\u0644\u0642\u0644\u0642\u0644\u0629 \u0648\u0647\u064a ( \u0642\u064f\u0637\u0652\u0628\u064f \u062c\u064e\u062f\u0652 ) \u0641\u064a\u062c\u0628 \u0623\u0646 \u0646\u0642\u0644\u0642\u0644\u0647 \u0639\u0646\u062f \u0627\u0644\u0648\u0642\u0641 \u0639\u0644\u064a\u0647\u060c \u0648\u0628\u0645\u0627 \u0623\u0646 \u062d\u0631\u0641 \u0627\u0644\u0642\u0627\u0641 \u0645\u064f\u0634\u062f\u0651\u062f \u0641\u064a\u062c\u0628 \u0627\u0644\u0627\u0646\u062a\u0628\u0627\u0647 \u0628\u0623\u0646 \u0644\u0627 \u064a\u0632\u0648\u0644 \u0627\u0644\u062a\u0634\u062f\u064a\u062f \u0628\u0627\u0644\u0642\u0644\u0642\u0644\u0629 \u0648\u064a\u064f\u0633\u0645\u064a \u0627\u0644\u0628\u0639\u0636 \u0647\u0630\u0647 \u0627\u0644\u0645\u0631\u062a\u0628\u0629 \u0645\u0646 \u0627\u0644\u0642\u0644\u0642\u0644\u0629 \u0628\u0627\u0644\u0642\u0644\u0642\u0644\u0629 \u0627\u0644\u0643\u0628\u0631\u0649\u060c \u0623\u0645\u0651\u0627 \u0639\u0646\u062f \u0627\u0644\u0648\u0635\u0644 \u0641\u0644\u0627 \u062a\u0638\u0647\u0631 \u0627\u0644\u0642\u0644\u0642\u0644\u0629 \u0644\u0623\u0646 \u062d\u0631\u0641 \u0627\u0644\u0642\u0644\u0642\u0644\u0629 \u063a\u064a\u0631 \u0633\u0627\u0643\u0646.")
B.aYS=new A.w("\u064a\u0632\u0648\u0644 \u0627\u0644\u062a\u0634\u062f\u064a\u062f \u0639\u0646\u062f \u0642\u0644\u0642\u0644\u0629 \u0627\u0644\u062d\u0631\u0641 \u0627\u0644\u0645\u0634\u062f\u062f \u0627\u0644\u0645\u0648\u0642\u0648\u0641 \u0639\u0644\u064a\u0647 \u0645\u062b\u0644 ( \u0648\u062a\u0628\u0651\u064e \u060c \u0627\u0644\u062d\u062c\u0651\u064f \u060c \u0627\u0644\u062d\u0642\u0651\u064f )",B.P,"\u062e\u0637\u0623","\u0644\u0627 \u064a\u0632\u0648\u0644 \u0627\u0644\u062a\u0634\u062f\u064a\u062f \u0639\u0646\u062f \u0642\u0644\u0642\u0644\u0629 \u0627\u0644\u062d\u0631\u0641 \u0627\u0644\u0645\u064f\u0634\u062f\u0651\u062f \u0627\u0644\u0645\u0648\u0642\u0648\u0641 \u0639\u0644\u064a\u0647\u060c \u0641\u064a\u062c\u0628 \u0627\u0644\u0625\u062a\u064a\u0627\u0646 \u0628\u0627\u0644\u062a\u0634\u062f\u064a\u062f \u0645\u0639 \u0627\u0644\u0642\u0644\u0642\u0644\u0629 \u0648\u064a\u064f\u0633\u0645\u064a \u0627\u0644\u0628\u0639\u0636 \u0647\u0630\u0647 \u0627\u0644\u0645\u0631\u062a\u0628\u0629 \u0645\u0646 \u0627\u0644\u0642\u0644\u0642\u0644\u0629 \u0628\u0627\u0644\u0642\u0644\u0642\u0644\u0629 \u0627\u0644\u0643\u0628\u0631\u0649.")
B.aWo=new A.w("\u062a\u0638\u0647\u0631 \u0627\u0644\u0642\u0644\u0642\u0644\u0629 \u0641\u064a \u062d\u0631\u0641 \u0627\u0644\u062f\u0627\u0644 \u0639\u0646\u062f \u0627\u0644\u0648\u0642\u0641 \u0639\u0644\u0649 \u0643\u0644\u0645\u0629 ( \u0623\u064e\u062d\u064e\u062f\u064c ) \u0641\u064a \u0642\u0648\u0644\u0647 \u062a\u0639\u0627\u0644\u0649: ( \u0642\u064f\u0644\u06e1 \u0647\u064f\u0648\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0623\u064e\u062d\u064e\u062f\u064c )",B.L,"\u0635\u062d","\u062a\u0638\u0647\u0631 \u0627\u0644\u0642\u0644\u0642\u0644\u0629 \u0641\u064a \u062d\u0631\u0641 \u0627\u0644\u062f\u0627\u0644 \u0639\u0646\u062f \u0627\u0644\u0648\u0642\u0641 \u0639\u0644\u0649 \u0643\u0644\u0645\u0629 ( \u0623\u064e\u062d\u064e\u062f\u064c ) \u0644\u0623\u0646\u0647 \u0641\u064a \u0646\u0647\u0627\u064a\u0629 \u0627\u0644\u0643\u0644\u0645\u0629\u060c \u0641\u0639\u0646\u062f \u0627\u0644\u0648\u0642\u0641 \u0639\u0644\u0649 \u062d\u0631\u0641 \u0627\u0644\u0642\u0644\u0642\u0644\u0629 \u062a\u0638\u0647\u0631 \u0641\u064a\u0647 \u0627\u0644\u0642\u0644\u0642\u0644\u0629 \u0633\u0648\u0627\u0621 \u0643\u0627\u0646 \u0633\u0627\u0643\u0646\u064b\u0627 \u0623\u0648 \u0645\u062a\u062d\u0631\u0643\u064b\u0627 \u0623\u0648 \u0645\u064f\u0646\u0648\u0651\u0646\u064b\u0627 \u0628\u0627\u0644\u0636\u0645 \u0623\u0648 \u0628\u0627\u0644\u0643\u0633\u0631\u060c \u0623\u0645\u0651\u0627 \u0625\u0630\u0627 \u0643\u0627\u0646 \u0645\u064f\u0646\u0648\u0651\u0646\u064b\u0627 \u0628\u0627\u0644\u0641\u062a\u062d \u0641\u0644\u0627 \u062a\u0638\u0647\u0631 \u0627\u0644\u0642\u0644\u0642\u0644\u0629 \u0644\u0623\u0646\u0647 \u064a\u064f\u0639\u0648\u0636 \u0639\u0646 \u0627\u0644\u062a\u0646\u0648\u064a\u0646 \u0628\u0623\u0644\u0641 \u0645\u062f\u064a\u0629 \u0641\u0644\u0627 \u064a\u062a\u0645 \u0627\u0644\u0648\u0642\u0641 \u0639\u0644\u0649 \u062d\u0631\u0641 \u0627\u0644\u0642\u0644\u0642\u0644\u0629.")
